mapper.select:
select count(m.id)
from xg_chat_message m
where m.del_flag = 0
  and m.sender_id = #{userId}
  and m.create_time >= #{start}
  and m.create_time < #{end}

select count(fr.id)
from xg_friend_relation fr
where fr.del_flag = 0
  and fr.user_id = #{userId}
  and fr.create_time >= #{start}
  and fr.create_time < #{end}
